<?php

declare(strict_types=1);

namespace Tests\Plugins\LegacyPasswords\Unit;

use PHPUnit\Framework\Attributes\DataProvider;
use PHPUnit\Framework\TestCase;
use Plugins\LegacyPasswords\Domain\Algorithms\Pbkdf2Hash;
use Tests\Plugins\LegacyPasswords\Support\Vectors;

final class Pbkdf2HashTest extends TestCase
{
    /**
     * The known-answer test. Every vector was generated by Python's
     * `hashlib.pbkdf2_hmac` and assembled into Django's string format, so the
     * expected bytes come from OpenSSL rather than from this code.
     */
    #[DataProvider('vectors')]
    public function test_it_reproduces_a_digest_python_produced(string $password, string $hash): void
    {
        $parsed = Pbkdf2Hash::parse($hash);

        self::assertNotNull($parsed, 'the vector should parse');
        self::assertTrue(
            hash_equals($parsed->derived(), $parsed->recompute($password)),
            'the recomputed digest does not match the one Python produced',
        );
    }

    /** @return iterable<string, array{string, string}> */
    public static function vectors(): iterable
    {
        foreach (Vectors::pbkdf2() as $i => $vector) {
            yield $i . ' ' . strtok($vector['hash'], '$') => [$vector['password'], $vector['hash']];
        }
    }

    #[DataProvider('vectors')]
    public function test_a_wrong_password_does_not_reproduce_the_digest(string $password, string $hash): void
    {
        $parsed = Pbkdf2Hash::parse($hash);

        self::assertNotNull($parsed);
        self::assertFalse(hash_equals($parsed->derived(), $parsed->recompute($password . 'x')));
    }

    public function test_it_reads_the_declared_fields(): void
    {
        $parsed = Pbkdf2Hash::parse(
            'pbkdf2_sha256$260000$aBcDeFgHiJkL$hi4yngU53R23HHl8EG6Z0i8eA7KCLIaegHx21tD6Sqs=',
        );

        self::assertNotNull($parsed);
        self::assertSame('sha256', $parsed->digest);
        self::assertSame(260000, $parsed->iterations);
        self::assertSame('aBcDeFgHiJkL', $parsed->salt);
        self::assertSame(32, \strlen($parsed->derived()));
    }

    /**
     * The derived length follows the DIGEST, and it is not written in the
     * string.
     *
     * Django always asks for exactly the underlying hash's digest size — 32
     * bytes for SHA-256, 20 for SHA-1 — and the format records nothing about
     * it. An implementation that hard-coded 32 would pass every SHA-256 vector
     * and fail every SHA-1 one, which is why both are in the table.
     */
    public function test_the_derived_length_follows_the_digest(): void
    {
        $sha1 = Pbkdf2Hash::parse('pbkdf2_sha1$100$aBcDeFgHiJkL$zS08ylYe20jS1h11vtHRRFwxUVY=');

        self::assertNotNull($sha1);
        self::assertSame(20, \strlen($sha1->derived()));
        self::assertSame(20, \strlen($sha1->recompute('secret')));
    }

    /**
     * The salt is TEXT, not decoded bytes.
     *
     * Django generates an alphanumeric salt string and hands those characters
     * to PBKDF2. This is the opposite convention from the scrypt and Firebase
     * paths, where the salt genuinely is encoded bytes — and getting them the
     * wrong way round is the most likely way to break either, because the
     * result is a valid digest that simply never matches.
     */
    public function test_the_salt_is_used_as_text_and_never_decoded(): void
    {
        // A salt that is also valid base64, so a decode would succeed and
        // silently produce different bytes rather than failing.
        $salt = 'YWJjZGVmZ2g';
        $hash = hash_pbkdf2('sha256', 'secret', $salt, 1000, 32, true);

        $stored = 'pbkdf2_sha256$1000$' . $salt . '$' . base64_encode($hash);
        $parsed = Pbkdf2Hash::parse($stored);

        self::assertNotNull($parsed);
        self::assertSame($salt, $parsed->salt, 'the salt must survive verbatim');
        self::assertTrue(hash_equals($parsed->derived(), $parsed->recompute('secret')));

        // And prove the alternative really would differ, so the test above is
        // about something.
        $decoded = hash_pbkdf2('sha256', 'secret', base64_decode($salt, true), 1000, 32, true);
        self::assertNotSame($hash, $decoded, 'decoding the salt gives different bytes, as expected');
    }

    #[DataProvider('malformed')]
    public function test_it_refuses_a_malformed_hash(string $stored, string $why): void
    {
        self::assertNull(Pbkdf2Hash::parse($stored), $why);
    }

    /** @return iterable<string, array{string, string}> */
    public static function malformed(): iterable
    {
        yield 'empty' => ['', 'an empty column is not a hash'];
        yield 'three fields' => ['pbkdf2_sha256$1000$salt', 'the digest field is missing'];
        yield 'two fields' => ['pbkdf2_sha256$1000', 'truncated'];
        yield 'no prefix' => ['sha256$1000$salt$aaaa', 'does not start with pbkdf2_'];
        yield 'unknown digest' => ['pbkdf2_md5$1000$salt$aaaa', 'md5 is not on the allowlist'];
        yield 'a checksum as the digest' => [
            'pbkdf2_crc32b$1000$salt$aaaa',
            'PBKDF2 over a 32-bit checksum is not an authentication check',
        ];
        yield 'empty salt' => ['pbkdf2_sha256$1000$$aaaa', 'no salt'];
        yield 'zero iterations' => [
            'pbkdf2_sha256$0$salt$' . base64_encode(random_bytes(32)), 'no work factor at all',
        ];

        // `(int) '1000x'` is 1000 and `(int) '1e6'` is 1 — both would parse a
        // corrupted field into a plausible number and hash with the wrong
        // cost, so the check is ctype_digit and not a cast.
        yield 'iterations with a trailing character' => [
            'pbkdf2_sha256$1000x$salt$' . base64_encode(random_bytes(32)),
            '(int) would read this as 1000',
        ];
        yield 'iterations in scientific notation' => [
            'pbkdf2_sha256$1e6$salt$' . base64_encode(random_bytes(32)),
            '(int) would read this as 1',
        ];
        yield 'negative iterations' => [
            'pbkdf2_sha256$-1000$salt$' . base64_encode(random_bytes(32)), 'not a count',
        ];

        yield 'iterations above the ceiling' => [
            'pbkdf2_sha256$99999999$salt$' . base64_encode(random_bytes(32)),
            'above MAX_ITERATIONS, which exists so a mistyped count cannot pin a worker',
        ];

        // The digest length must match the declared algorithm, or a hash from
        // a tool that asked for 64 bytes would be derived at 32, compared
        // against 64, and every user told their password was wrong.
        yield 'digest too short for sha256' => [
            'pbkdf2_sha256$1000$salt$' . base64_encode(random_bytes(20)), '20 bytes is sha1 length',
        ];
        yield 'digest too long for sha256' => [
            'pbkdf2_sha256$1000$salt$' . base64_encode(random_bytes(64)), '64 bytes is sha512 length',
        ];

        // Lenient base64_decode() silently drops characters it does not
        // recognise, so a corrupted field would decode to something shorter —
        // strict mode is what turns that into a refusal.
        yield 'digest that is not base64' => [
            'pbkdf2_sha256$1000$salt$not-valid-base64!!!', 'strict decoding must reject it',
        ];
    }

    /**
     * A salt containing `$` is read up to the next separator, as Django does.
     *
     * Django splits on `$` with a limit, so the behaviour is matched rather
     * than improved on: a salt with a `$` in it is something Django could not
     * have written, and inventing a different reading would make this parser
     * disagree with the system that produced the data.
     */
    public function test_the_field_split_matches_djangos(): void
    {
        // Four fields where the last absorbs any remaining `$`. A base64
        // digest never contains one, so this only arises from a salt that
        // does — and then the digest field would carry it and fail to decode.
        self::assertNull(Pbkdf2Hash::parse('pbkdf2_sha256$1000$sa$lt$aaaa'));
    }
}
